	@Test
	void explicitModesApplyToEveryQueryForm() {
		var parser = new SPARQLParser();
		for (String text : List.of(
				"SELECT * WHERE { GRAPH ?g { ?s <urn:p> ?o } }",
				"ASK { GRAPH ?g { ?s <urn:p> ?o } }",
				"CONSTRUCT { ?s <urn:p> ?o } WHERE { GRAPH ?g { ?s <urn:p> ?o } }",
				"DESCRIBE ?s WHERE { GRAPH ?g { ?s <urn:p> ?o } }")) {
			var legacy = parser.parseQuery(text, null, LEGACY);
			var graph = parser.parseQuery(text, null, GRAPH);
			assertThat(nodes(legacy.getTupleExpr(), Graph.class)).as(text).isEmpty();
			assertThat(nodes(legacy.getTupleExpr(), StatementPattern.class)).as(text).allSatisfy(pattern -> {
				assertThat(pattern.getScope()).isEqualTo(StatementPattern.Scope.NAMED_CONTEXTS);
				assertThat(pattern.getContextVar().getName()).isEqualTo("g");
			});
			assertThat(nodes(graph.getTupleExpr(), Graph.class)).as(text).hasSize(1);
		}
	}

	@Test
	void legacyEmptyAndBindOnlyGraphsKeepTheirHistoricalLimitations() {
		var parser = new SPARQLParser();
		for (String body : List.of("", "BIND(1 AS ?v)")) {
			String text = "SELECT ?g ?v WHERE { GRAPH ?g { " + body + " } }";
			var legacy = parser.parseQuery(text, null, LEGACY);
			var graph = parser.parseQuery(text, null, GRAPH);

			assertThat(nodes(legacy.getTupleExpr(), Graph.class)).isEmpty();
			assertThat(nodes(legacy.getTupleExpr(), StatementPattern.class)).isEmpty();
			assertThat(nodes(legacy.getTupleExpr(), Var.class)).noneMatch(variable -> variable.getName().equals("g"));
			assertThat(nodes(graph.getTupleExpr(), Graph.class)).singleElement().satisfies(boundary -> {
				assertThat(boundary.getGraphName().getName()).isEqualTo("g");
				assertThat(boundary.getAssuredBindingNames()).contains("g");
			});
		}
	}

