	@Test
	void updateModesAffectWhereButNotQuadTemplates() {
		for (QueryParseOptions options : List.of(LEGACY, GRAPH)) {
			var update = new SPARQLParser().parseUpdate(
					"DELETE { GRAPH ?g { ?s <urn:p> ?o } } INSERT { GRAPH ?g { ?s <urn:copy> ?o } } "
							+ "WHERE { GRAPH ?g { ?s <urn:p> ?o } }",
					null, options);
			var modify = (Modify) update.getUpdateExprs().getFirst();

			assertThat(update.getParseOptions()).isEqualTo(options);
			assertThat(nodes(modify.getWhereExpr(), Graph.class))
					.hasSize(options.graphAlgebraMode() == GraphAlgebraMode.GRAPH ? 1 : 0);
			for (var template : List.of(modify.getDeleteExpr(), modify.getInsertExpr())) {
				assertThat(nodes(template, Graph.class)).isEmpty();
				assertThat(nodes(template, StatementPattern.class)).singleElement().satisfies(pattern -> {
					assertThat(pattern.getContextVar().getName()).isEqualTo("g");
					assertThat(pattern.getScope()).isEqualTo(StatementPattern.Scope.NAMED_CONTEXTS);
				});
			}
		}
	}

